def shortest_path(N, M, grid):
    from collections import deque

    # If the starting or ending point is blocked, return -1
    if grid[0][0] == 1 or grid[N-1][M-1] == 1:
        return -1

    # Directions for moving up, down, left, right
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
    queue = deque([(0, 0, 1)])  # (row, col, distance)
    visited = set((0, 0))

    while queue:
        x, y, dist = queue.popleft()

        # If we reach the bottom-right corner, return the distance
        if x == N - 1 and y == M - 1:
            return dist

        for dx, dy in directions:
            nx, ny = x + dx, y + dy

            # Check if the new position is within bounds and not blocked
            if 0 <= nx < N and 0 <= ny < M and grid[nx][ny] == 0 and (nx, ny) not in visited:
                visited.add((nx, ny))
                queue.append((nx, ny, dist + 1))

    return -1  # No path found

# Example usage
if __name__ == '__main__':
    grid1 = [[0, 0, 0], [1, 1, 0], [1, 0, 0]]
    print(shortest_path(3, 3, grid1))  # Output: 4

    grid2 = [[0, 1, 0], [1, 1, 0], [1, 0, 0]]
    print(shortest_path(3, 3, grid2))  # Output: -1"
        }
